// Downloads the Google font families listed in shared/fonts.ts into
// public/fonts/google/ so the app never talks to Google at runtime.
//
// Output (git-ignored, regenerated by `bun run fonts`, dev, build and Docker):
//   *.woff2        one file per family/unicode-range slice/weight
//   fonts.css      @font-face rules for the DOM preview (same-origin URLs)
//   manifest.json  { family: [{ file, weight, style, ranges }] } for the exporter
//
// Idempotent: skipped when manifest.json already matches the family list.
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { GOOGLE_FONTS, GOOGLE_FONT_BASE } from "../shared/fonts.ts";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outDir = path.join(root, "public", GOOGLE_FONT_BASE);
const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36";

const signature = JSON.stringify(GOOGLE_FONTS);

async function upToDate() {
  try {
    const m = JSON.parse(await readFile(path.join(outDir, "manifest.json"), "utf8"));
    return m.signature === signature;
  } catch {
    return false;
  }
}

const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-");

function parseRanges(value) {
  if (!value) return [];
  return value.split(",").map((r) => {
    const t = r.trim().replace(/^U\+/i, "");
    if (t.includes("-")) {
      const [a, b] = t.split("-");
      return [parseInt(a, 16), parseInt(b, 16)];
    }
    if (t.includes("?"))
      return [parseInt(t.replace(/\?/g, "0"), 16), parseInt(t.replace(/\?/g, "F"), 16)];
    const n = parseInt(t, 16);
    return [n, n];
  });
}

async function get(url, init) {
  for (let attempt = 1; ; attempt++) {
    try {
      const res = await fetch(url, init);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res;
    } catch (err) {
      if (attempt >= 3) throw new Error(`${url}: ${err.message}`);
      await new Promise((r) => setTimeout(r, 500 * attempt));
    }
  }
}

async function mapLimit(items, limit, fn) {
  let i = 0;
  await Promise.all(
    Array.from({ length: limit }, async () => {
      while (i < items.length) await fn(items[i++]);
    }),
  );
}

if (await upToDate()) {
  console.log("[fonts] up to date");
  process.exit(0);
}

await mkdir(outDir, { recursive: true });
const manifest = { signature, families: {} };
const css = [];
const downloads = [];

for (const { name, weights } of GOOGLE_FONTS) {
  const family = `${name.replace(/ /g, "+")}:wght@${weights.join(";")}`;
  const sheet = await (
    await get(`https://fonts.googleapis.com/css2?family=${family}&display=swap`, {
      headers: { "User-Agent": UA },
    })
  ).text();

  const faces = [];
  let n = 0;
  for (const m of sheet.matchAll(/(?:\/\*\s*([^*]+?)\s*\*\/\s*)?@font-face\s*\{([^}]*)\}/g)) {
    const body = m[2];
    const url = body.match(/src:\s*url\(([^)]+)\)/)?.[1]?.replace(/['"]/g, "");
    const weight = Number(body.match(/font-weight:\s*(\d+)/)?.[1] ?? 400);
    const style = body.match(/font-style:\s*(\w+)/)?.[1] ?? "normal";
    const range = body.match(/unicode-range:\s*([^;]+)/)?.[1];
    if (!url) continue;
    const subset = slug(m[1] ?? `s${n}`);
    const file = `${slug(name)}-${subset}-${weight}.woff2`;
    n++;
    downloads.push({ url, file });
    faces.push({ subset, file, weight, style, ranges: parseRanges(range) });
    css.push(
      `@font-face{font-family:"${name}";font-style:${style};font-weight:${weight};font-display:swap;` +
        `src:url(${GOOGLE_FONT_BASE}/${file}) format("woff2");` +
        (range ? `unicode-range:${range};` : "") +
        `}`,
    );
  }
  if (faces.length === 0) throw new Error(`no @font-face parsed for ${name}`);
  manifest.families[name] = faces;
  console.log(`[fonts] ${name}: ${faces.length} slices`);
}

let done = 0;
await mapLimit(downloads, 8, async ({ url, file }) => {
  const buf = Buffer.from(await (await get(url)).arrayBuffer());
  await writeFile(path.join(outDir, file), buf);
  if (++done % 100 === 0) console.log(`[fonts] ${done}/${downloads.length} files`);
});

await writeFile(path.join(outDir, "fonts.css"), css.join("\n") + "\n");
await writeFile(path.join(outDir, "manifest.json"), JSON.stringify(manifest));
console.log(`[fonts] done: ${downloads.length} files`);
